// ---------------------------------------------------------------------------
// Main
// ---------------------------------------------------------------------------

async function main() {
  console.log("[seed-new-collection] Starting...");
  console.log("[seed-new-collection] NON-DESTRUCTIVE: old products deactivated (not deleted), new products upserted.");

  // 1. Deactivate ONLY the known old products from the previous collection.
  //
  // SAFETY: This uses an EXPLICIT WHITELIST of old product slugs (the 9
  // products created by the original /api/admin/setup route). It does NOT
  // use a blanket `where: { active: true }` that would deactivate ALL
  // active products — including any products the admin may have created
  // manually after the initial setup.
  //
  // The 9 old slugs are:
  //   - dw-01, dw-02, dw-03, dw-04  (8 PRODUCTS in src/lib/site-data.ts, ids dw-* / na-* / bs-*)
  //   - na-01, na-02               (created by setup route as upserts)
  //   - bs-01, bs-02
  //   - royal-pleated-abaya        (created by setup route, 9th product)
  //
  // If any of these slugs don't exist in the target DB (e.g., the admin
  // already deleted one, or this is a fresh DB), updateMany silently skips
  // them (count = number of rows actually matched). This is safe.
  //
  // Products NOT in this whitelist are left UNTOUCHED — whether active or
  // inactive. This means:
  //   - The 10 NEW products (noor-everyday-abaya, etc.) are NOT deactivated
  //     by this step (they're upserted in step 2 with active = true).
  //   - Any manually-created admin products are NOT deactivated.
  //
  // Idempotent: running this twice produces the same final state (the 9 old
  // slugs stay active=false; the 10 new slugs stay active=true).
  const OLD_PRODUCT_SLUGS = [
    "dw-01", "dw-02", "dw-03", "dw-04",
    "na-01", "na-02",
    "bs-01", "bs-02",
    "royal-pleated-abaya",
  ];

  console.log(`[seed-new-collection] Deactivating ${OLD_PRODUCT_SLUGS.length} known old products (explicit whitelist):`);
  OLD_PRODUCT_SLUGS.forEach((s) => console.log(`  - ${s}`));

  const deactivateResult = await db.product.updateMany({
    where: { slug: { in: OLD_PRODUCT_SLUGS } },
    data: { active: false },
  });
  console.log(`[seed-new-collection] Deactivated ${deactivateResult.count} old products (active = false). Rows preserved (NOT deleted).`);
  console.log(`[seed-new-collection] (count < ${OLD_PRODUCT_SLUGS.length} means some slugs weren't found — safe, they're skipped.)`);

  // 2. Upsert the 10 new products.
  let created = 0;
  let updated = 0;
  for (const p of COLLECTION) {
    // Build the image paths from the generated images.
    const imgBase = `/images/products/new-collection/${p.slug}`;
    const colorNameToFile = (hex: string) => {
      const map: Record<string, string> = {
        "#1a1a1a": "black", "#6b5246": "mocha", "#8a9a7b": "sage",
        "#3a3633": "charcoal", "#b87878": "dusty-rose", "#1a6b6b": "teal",
        "#2a3441": "navy", "#e8dcc4": "cream",
        "#5c1a2b": "burgundy", "#1a4d3a": "forest-green", "#c9a24b": "gold",
        "#9a7a8a": "mauve", "#e8d4a8": "champagne",
        "#6b1f2e": "maroon", "#1e6b50": "emerald-green",
        "#d8c7a8": "beige", "#6b7a3a": "olive", "#a84c2c": "rust",
        "#e8c4c4": "blush-pink", "#c4b0d4": "lavender", "#a8c4e8": "sky-blue",
        "#722f37": "wine",
      };
      return map[hex.toLowerCase()] || hex.replace("#", "");
    };

    // Default gallery: use the color-specific images (one per color).
    const galleryImages = p.colors.map((c) => `${imgBase}/${colorNameToFile(c.hex)}-1.png`);

    // Color-specific images (colorImages JSON).
    const colorImages = p.colors.map((c) => ({
      colorHex: c.hex,
      colorName: c.name,
      image: `${imgBase}/${colorNameToFile(c.hex)}-1.png`,
      images: [],
    }));

    // Combination images.
    const combinationImages = p.combos.map((combo) => ({
      colorHex: combo.colorHex,
      styleId: combo.styleId,
      fabricId: combo.fabricId,
      image: `${imgBase}/${combo.suffix}.png`,
      images: [],
    }));

    const existing = await db.product.findUnique({ where: { slug: p.slug } });
    const data = {
      name: p.name,
      category: p.category,
      price: p.price,
      originalPrice: p.originalPrice ?? null,
      image: galleryImages[0],
      images: JSON.stringify(galleryImages),
      colorImages: JSON.stringify(colorImages),
      colors: JSON.stringify(p.colors.map((c) => ({ hex: c.hex, name: c.name }))),
      sizes: JSON.stringify(ALL_SIZES),
      styleOptions: JSON.stringify(p.styles),
      fabricOptions: JSON.stringify(p.fabrics),
      combinationImages: JSON.stringify(combinationImages),
      badge: p.badge ?? null,
      fabric: p.fabric,
      care: p.care,
      description: p.description,
      stock: p.stock,
      active: true,
      isNewArrival: p.isNewArrival,
      isBestSeller: p.isBestSeller,
      isFeatured: p.isFeatured,
    };

    if (existing) {
      await db.product.update({ where: { slug: p.slug }, data });
      updated++;
    } else {
      await db.product.create({
        data: {
          slug: p.slug,
          ...data,
          rating: 5.0,
          reviewCount: 0,
          lowStockThreshold: 5,
        },
      });
      created++;
    }
    console.log(`  [${existing ? "update" : "create"}] ${p.slug} — ${p.colors.length} colors, ${p.styles.length} styles, ${p.fabrics.length} fabrics, ${p.combos.length} combos`);
  }

  // 3. Final counts.
  const newActive = await db.product.count({ where: { active: true } });
  const totalProducts = await db.product.count();
  const oldInactive = await db.product.count({ where: { active: false } });

  console.log("");
  console.log("=== SUMMARY ===");
  console.log(`New products created: ${created}`);
  console.log(`New products updated: ${updated}`);
  console.log(`Total products in DB: ${totalProducts}`);
  console.log(`Active products (new collection): ${newActive}`);
  console.log(`Inactive products (old collection, preserved): ${oldInactive}`);
  console.log("");
  console.log("[seed-new-collection] DONE. Old products deactivated (NOT deleted). New products active.");
  console.log("[seed-new-collection] Existing orders, OrderItems, reviews, wishlists, users — all preserved.");
}

main()
  .catch((e) => {
    console.error("[seed-new-collection] ERROR:", e instanceof Error ? e.message : e);
    process.exit(1);
  })
  .finally(async () => {
    await db.$disconnect();
  });
